    assertTrue(index.contains("class=\"product-link\" href=\"" + PROJECT_URL + "\" "
        + EXTERNAL_LINK_ATTRIBUTES + ">kkRepo</a>"));
    assertTrue(index.contains("class=\"product-link\" href=\"" + PROJECT_URL + "\" "
