        using var body = new MemoryStream();
        var buffer = new byte[8192];
        while (true)
        {
            var count = await source.ReadAsync(buffer.AsMemory(0, Math.Min(buffer.Length, maximum_bytes + 1 - checked((int)body.Length))), cancellationToken).ConfigureAwait(false);
            if (count == 0)
