  const definitions = [
    { id: 'weeklyTopics', key: 'semanal', label: 'Tópicos na semana', description: 'Tópicos concluídos nesta semana' },
    { id: 'monthlyTopics', key: 'mensal', label: 'Tópicos no mês', description: 'Tópicos concluídos neste mês' },
