  ];
  const items = definitions.map(i => {
    const target = goals[i.key] == null ? null : Math.max(0, number(goals[i.key]));
    const current = Math.max(0, number(achieved[i.id]));
    const measured = i.id !== 'accuracy' || achieved.accuracy != null;
    const value = i.id === 'accuracy' ? (measured ? number(achieved.accuracy) : null) : current;
