    float yaw = mc.player.getYaw();
    float pitch = mc.player.getPitch();
    if (lastNanos == 0) {
        lastNanos = NOW;
        lastYaw = yaw;
        lastPitch = pitch;
        return;
    }
    float dt = Math.max(0.0005f, Math.min(0.1f, (NOW - lastNanos) / 1_000_000_000f));
    lastNanos = NOW;
