async function resolve_bundle_file(arg) {
  const isFilePath =
    arg.endsWith('.json') ||
    arg.endsWith('.txt') ||
    arg.startsWith('./') ||
    arg.startsWith('../') ||
    arg.startsWith('/') ||
    arg.startsWith('~')
  if (isFilePath) {
    const resolvedPath = expandTilde(arg, process.env.HOME || '/tmp')
    for (const candidate of [resolvedPath, join(process.cwd(), arg)]) {
      try {
        await readFile(candidate, 'utf-8')
        return candidate
      } catch {}
    }
    throw new Error(`Bundle file not found: ${arg}`)
  }

  const candidates = [
    arg,
    join(process.cwd(), arg),
    `${arg}.json`,
    `${arg}.txt`,
    join(process.cwd(), `${arg}.json`),
    join(process.cwd(), `${arg}.txt`),
  ]

  for (const candidate of candidates) {
    try {
      await readFile(candidate, 'utf-8')
      return candidate
    } catch {}
  }
  return null
}
```

