public static int tier_color(String tier) {
    boolean high = tier.contains("HT");
    int n = 5;
    for (int i = tier.length() - 1; i >= 0; i--) {
        if (Character.isDigit(tier.charAt(i))) {
            n = tier.charAt(i) - '0';
            break;
